<script setup>const props = defineProps({ item: { type: Object, required: true }, active: Boolean, collapsed: Boolean }); const emit = defineEmits(['navigate']);</script>
<template><RouterLink :to="item.to" custom v-slot="{ navigate }"><button :title="collapsed ? item.label : undefined" :class="['mb-px flex w-full items-center rounded-md py-[7px] text-[13px] transition-colors', collapsed ? 'justify-center px-2' : 'gap-2.5 px-2.5', active ? 'bg-[#EEF2F8] font-medium text-[#173B6C]' : 'text-[#5E6E82] hover:bg-[#F5F7FA] hover:text-[#172033]']" @click="() => { navigate(); emit('navigate'); }"><component :is="item.icon" :size="16" :class="['shrink-0', active ? 'text-[#173B6C]' : 'text-[#A0AABB]']" /><span v-if="!collapsed" class="flex-1 text-left">{{ item.label }}</span><span v-if="active && !collapsed" class="h-3.5 w-1 shrink-0 rounded-full bg-[#173B6C]" /></button></RouterLink></template>
